const body = $input.first().json.body ?? $input.first().json;
const trace_id = body.trace_id ?? ('health-' + Date.now());

// Support both direct POST and openclaw.health event envelope
const payload = body.event?.payload ?? body;

const status      = payload.status      ?? 'offline';
const version     = payload.version     ?? null;
const gateway     = payload.gateway     ?? false;
const rpc         = payload.rpc         ?? false;
const memSearch   = payload.memory_search ?? 'missing';
const telegram    = payload.channels?.telegram ?? 'unknown';
const whatsapp    = payload.channels?.whatsapp ?? 'unknown';
const timestamp   = payload.timestamp   ?? new Date().toISOString();

return [{ json: {
  trace_id,
  status,
  version,
  gateway,
  rpc,
  memory_search: memSearch,
  channels: { telegram, whatsapp },
  timestamp,
  needs_alert: status !== 'healthy',
  alert_level: status === 'offline' ? 'urgent' : status === 'degraded' ? 'warning' : 'none',
} }];

const d = $input.first().json;
const ts = new Date(d.timestamp).toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
const msg = [
  '🚨 *OpenClaw OFFLINE*',
  '',
  `Gateway: ${d.gateway ? '✓' : '✗'} reachable`,
  `RPC:     ${d.rpc     ? '✓' : '✗'} responding`,
  `Version: ${d.version ?? 'unknown'}`,
  '',
  `Checked: ${ts}`,
  '',
  'Run: `openclaw gateway start`',
].join('\n');
return [{ json: { ...d, alert_message: msg } }];

const d = $input.first().json;
const ts = new Date(d.timestamp).toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
const issues = [];
if (d.memory_search === 'missing') issues.push('• Memory search has no local model');
if (d.channels.telegram === 'disconnected') issues.push('• Telegram disconnected');
if (d.channels.whatsapp === 'not_linked') issues.push('• WhatsApp not linked');
const msg = [
  '⚠️ *OpenClaw DEGRADED*',
  '',
  ...issues,
  '',
  `Version: ${d.version ?? 'unknown'}`,
  `Checked: ${ts}`,
  '',
  'Run: `openclaw doctor --fix`',
].join('\n');
return [{ json: { ...d, alert_message: msg } }];

// ── Telegram alert sender ────────────────────────────────────────────────────
// Reads credentials from n8n environment variables.
// Set TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in your n8n instance
// (Settings → Environment Variables) or export them in the n8n process env.
const BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN ?? '';
const CHAT_ID   = $env.TELEGRAM_CHAT_ID   ?? '';

const d   = $input.first().json;
const msg = d.alert_message;

if (!BOT_TOKEN || !CHAT_ID) {
  return [{ json: { ...d, telegram_sent: false, reason: 'TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID not set — add them to n8n environment variables' } }];
}

try {
  const res = await helpers.httpRequest({
    url: 'https://api.telegram.org/bot' + BOT_TOKEN + '/sendMessage',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: { chat_id: CHAT_ID, text: msg, parse_mode: 'Markdown' },
    json: true,
  });
  return [{ json: { ...d, telegram_sent: true, tg_message_id: res.result?.message_id } }];
} catch (err) {
  return [{ json: { ...d, telegram_sent: false, tg_error: err.message } }];
}

const d = $input.first().json;
const ts = new Date(d.timestamp).toLocaleTimeString('en-US', { timeZone: 'America/Los_Angeles' });
console.log(`[OpenClaw] HEALTHY @ ${ts} — v${d.version ?? '?'} gateway=${d.gateway} rpc=${d.rpc} mem=${d.memory_search} tg=${d.channels.telegram}`);
return [{ json: { ...d, logged: true } }];
